#!/usr/bin/env python3
"""Render existing graph semantics into the existing 114 packets and 10 fragments.
This does not create tasks, reset status, or supply new architecture."""
from pathlib import Path
import json,hashlib
p=Path(__file__).resolve().parents[1]
load=lambda f:json.loads(Path(f).read_text())
dump=lambda f,x:Path(f).write_text(json.dumps(x,ensure_ascii=False,indent=2)+"\n")
sha=lambda f:hashlib.sha256(Path(f).read_bytes()).hexdigest()
graphs={k:load(p/(k+'-graph.json')) for k in ['research','documentation','delivery']}
nodes={n['id']:n for g in graphs.values() for n in g['nodes']}
ver=graphs['delivery']['revision']
registry=load(p.parent/'NativeWeave-Design/docs/contracts/registry.json')
contracts={c['id']:c for c in registry['contracts']}
fragments={'D22':('interop-foundation',['A01','A02','A03','A04','A05']),'D23':('generation',['A09','A10','A11','A12']),'D24':('async-runtime',['A06','A07','A08']),'D25':('build-release',['A13','A14','A15','A16']),'D26':('verification-engines',['A17','A18','A19','A20','A21','A23']),'D27':('database',[f'B{i:02d}' for i in range(1,9)]),'D28':('orm',[f'B{i:02d}' for i in range(9,15)]),'D29':('server',[f'B{i:02d}' for i in range(15,21)]),'D30':('end-to-end',[f'B{i:02d}' for i in range(21,25)]),'D31':('evolution',['A22','A24'])}
(p/'fragments').mkdir(exist_ok=True)
mirrored=['title','boundary_and_ownership','native_reuse','csharp_surface','implementation_steps','error_cancellation_resources_concurrency','specific_acceptance','write_scopes','dependency_rationale','verification_matrix','api_design_inputs','api_design_input_sha256','api_contract_types','api_surface_responsibility','documentation_owner_role','documentation_outputs']
for did,(name,ids) in fragments.items():
 content={'schema_version':'1.0.0','documentation_task_id':did,'revision':ver,'role':'Detailed implementation instructions for existing tasks; delivery-graph.json is the sole scheduling graph.','delivery_task_ids':ids,'design_inputs':[{'id':ref,'outputs':nodes[ref]['outputs']} for ref in nodes[did]['research_refs']+nodes[did]['documentation_refs']],'task_details':{id:{k:nodes[id][k] for k in mirrored} for id in ids},'worktree_policy':'One branch/worktree per task, exact owned scopes; root solution/Cargo workspace registration is an A13 integration patch under the small workspace-manifest lock. No global worker lock.','phase_authorization':'No product writes or A/B execution authorized in this research/design turn.'}
 if did=='D31':content['evolution_rules']=['Four independent identities: source/crate, C ABI, C# API and domain semantics; record relation rather than merge versions.','Any changed accepted input invalidates dependent review by exact hash/revision snapshot; re-review affected slice, not every unrelated task.','Controlled fork requires upstream base/patch queue/license/security owner/exit condition and direct-native regression oracles.','New Engine uses existing schema/contracts and a scoped task/fragment amendment in the existing three graphs, no fourth workflow.','No automatic production dependency promotion; security exception records reason and exact update evidence.']
 dump(p/'fragments'/f'{name}.json',content)
# Render all 114 self-contained packets from current task semantics; no obsolete appended policy text survives.
def bullets(items):
 if isinstance(items,str):return items+'\n'
 return '\n'.join('- '+('; '.join(str(v) for v in x) if isinstance(x,list) else str(x)) for x in items)+'\n'
def reference_table(n):
 rows=['| Input | Exact requirement |','| --- | --- |']
 rows += [f'| {id} | task revision {v}; the three graphs bind sources and acceptance evidence |' for id,v in n['dependency_pins'].items()]
 rows += [f'| {c["id"]} | {c["version"]}; `{contracts[c["id"]]["spec_path"]}`; SHA-256 `{contracts[c["id"]]["content_sha256"]}`; the acceptance record for the same content is authoritative |' for c in n['contract_inputs']]
 return '\n'.join(rows)
mandate='C# is the strongly typed application layer; database/ORM queries and relationships and Server networking/protocol runtimes must be implemented by mature Rust engines. Kestrel/managed drivers are comparison baselines only. Ordinary Entity/DTO/Handler code uses maintainer-precompiled native modules with normal dotnet build/run and AOT; do not reimplement a C# SQL AST/dialects/full LINQ or introduce a mandatory monolithic Core runtime.'
for kind,g in graphs.items():
 for n in g['nodes']:
  id=n['id'];s=f'# {id} — {n["title"]}\n\nTask revision **{n["revision"]}**. Graph: `{kind}-graph.json`; the graph is authoritative for current status, exact source commits, and acceptance records. This is one of the existing 114 independent task packets.\n\n## Objective and Phase\n\n{mandate}\n\nThe current scope is Research/Documentation and Design research prototypes only; future Delivery implementation still requires explicit phase authorization. Design acceptance must not be presented as successful product, long-running-load, or release acceptance.\n\n## Inputs, Dependencies, and Versions\n\n{reference_table(n)}\n\nStart dependencies: {", ".join(n["start_dependencies"]) or "no task-completion prerequisite"}. Acceptance dependencies: {", ".join(n["acceptance_dependencies"]) or "no additional task-completion prerequisite"}. Research references: {", ".join(n["research_refs"]) or "actual source for this task"}. Specification references: {", ".join(n["documentation_refs"]) or "outputs/registry for this task"}. References provide traceability; references not listed as dependencies do not impose global waiting.\n\n## File Ownership\n\n'+bullets(n['write_scopes'])
  if kind=='delivery':
   if 'api_design_inputs' in n:
    s+='\n## Public API and Documentation Contract\n\n'+bullets(n['api_design_inputs'])+'\nEach input is SHA-256 pinned in this node\'s `api_design_input_sha256`, and the entire Design repository is commit-pinned in `source-driven-baseline.json`.\n\nSurface responsibility: '+n['api_surface_responsibility']+'\n\nRelated exact public type policies:\n\n'+bullets(n['api_contract_types'] or ['No new public application type is assigned; apply the internal, verification, packaging or integration responsibility above.'])+'\nDocumentation owner: `'+n['documentation_owner_role']+'`. Implement XML, generated API Reference, guides and minimal/advanced consumers with this task; shared pipeline ownership does not defer module documentation. See `api-execution-requirements.md`.\n\nTask-owned documentation and example outputs:\n\n'+bullets(n['documentation_outputs'])
   s+=f'\nIndependent worktree/branch: `{n["parallel_worktree"]}`. Modify only the scopes above; A13 integrates patches to the root solution/Cargo workspace/shared build files. Do not overwrite other modules or lock all workers.\n\n## Modules and Interfaces\n\n{n["boundary_and_ownership"]}\n\nC# interfaces:\n\n'+bullets(n['csharp_surface'])+'\nRust native reuse:\n\n'+bullets(n['native_reuse'])+'\n## Implementation Steps\n\n'+'\n'.join(f'{i+1}. {v}' for i,v in enumerate(n['implementation_steps']))+'\n\n## Errors, Cancellation, Memory, and Concurrency\n\n'+bullets(n['error_cancellation_resources_concurrency'])+'\n## Acceptance Requirements\n\n'+bullets(n['specific_acceptance'])+'\n'+bullets(list(n['verification_matrix'].values()))+f'\nDependency rationale: {n["dependency_rationale"]}\n\n## Delivery and Review\n\nSubmit actual product changes, corresponding tests/logs/artifact SHAs, native and C# input identities, failure records, and independent technical review; write evidence to Plan:ledger/evidence/{id}/. Existing Design experiments are implementation oracles; do not copy their passed results as evidence that this task passed. Execution is allowed only when implementation authorization in the current graph, relevant contracts, and local dependencies hold.\n'
  elif kind=='research':
   s+='\n## Existing Results and Research Scope\n\nFirst read existing reports/evidence/coverage and use the takeover audit to distinguish stale status from actual gaps; recheck complete results without repeating the work.\n\n'+bullets(n['outputs'])+'\nResearch questions:\n\n'+bullets(n.get('questions',[]))+'\nSource mechanisms:\n\n'+bullets(n.get('symbol_targets',[]))+'\n## Actual Execution and Failure Paths\n\n'+bullets(n.get('failure_paths',[]))+'\n1. Pin actual source/versions/commits/crate checksums/features; list only symbols and scopes actually read.\n2. Distinguish upstream tests read, research experiments executed, and product verification awaiting implementation; establish traceable conclusions for normal/failure/critical-boundary cases.\n3. For appropriate experiments, preserve complete commands, input/output hashes, target platforms, actual execution, and failures; do not mark unexecuted work as passed.\n4. State technical decisions, alternative tradeoffs, and remaining product obligations; correct old conflicts directly rather than merely adding appendices.\n5. Before acceptance, independently review the exact outputs, resolve blockers, and then bind the current graph subject to actual evidence.\n\n## Basis for Completion\n\n'+str(n.get('verification','Pinned source, necessary experiments, and independent review.'))+'\n\nCurrent substantive results are defined by report.md/evidence.json/coverage.json; subsequently reopen only affected scopes when sources or interfaces change. Research does not require future product implementation first.\n'
  else:
   s+='\n## Specification Scope and Concrete Outputs\n\n'+n['specific_scope']+'\n\n'+bullets(n['outputs'])+'\n## Preparation and Acceptance Steps\n\n1. Read relevant existing research and pinned source/experiments, reusing successful results; distinguish new decisions in this document from historical observations.\n2. Specify explicit Rust/C# interfaces, reuse of mature native capabilities, and ABI/state-machine/ownership/threading/cancellation/error/release/platform rules.\n3. Define ordinary precompiled consumption, static AOT mapping, necessary implementation examples, and executable test acceptance; do not make product implementation a circular prerequisite for design.\n4. Assign actual future obligations to existing Delivery IDs, file scopes, local dependencies, and worktrees; fragments only elaborate the existing graphs.\n5. Independently review consistency between the specification and research/contracts/tasks, resolve all blockers, and bind exact hashes/versions/sources.\n\n## Review Evidence\n\nContract outputs: '+(', '.join(n.get('contract_outputs',[])) or 'no separate contract; detailed instructions for existing tasks/overall independent review')+'. The registry and graphs preserve current formal acceptance evidence; this packet does not grant itself acceptance. Product long-running loads, actual releases, and production support still require Delivery evidence.\n'
  file=p/n['prompt'];file.parent.mkdir(parents=True,exist_ok=True);file.write_text(s);n['packet_sha256']=sha(file)
for kind,g in graphs.items():dump(p/(kind+'-graph.json'),g)
# Canonical inventory remains exactly 114 IDs.
s=f'# NativeWeave Task Index\n\nThe existing three graphs contain 34 Research, 32 Documentation, and 48 future Delivery tasks. Current graph revision {ver}; individual packet revisions are explicit. The graphs are authoritative for status/acceptance, and product implementation is currently unauthorized.\n'
for kind,g in graphs.items():
 s+=f'\n## {kind}\n\n| ID | Task | Independent packet |\n| --- | --- | --- |\n'
 for n in g['nodes']:s+=f'| {n["id"]} | {n["title"]} | [{n["id"]}]({n["prompt"]}) |\n'
(p/'task-index.md').write_text(s)
print('updated 114 nodes/packets, 10 required fragments; no product files written')
